    for (index, (a, b)) in cases.into_iter().enumerate() {
        let a = a.map(v);
        let b = b.map(v);
        let result = triangles_intersect(a, b);
        let expected = reference::triangle_reference(a, b);
        let tolerance = a.iter().chain(&b).map(|p| p.abs().max_element()).fold(0.0_f32, f32::max) * 1e-4;
        match (&expected, result) {
            (reference::ReferenceIntersection::Disjoint, TriangleTriangleIntersection::Disjoint)
            | (reference::ReferenceIntersection::Coplanar, TriangleTriangleIntersection::Coplanar) => {},
            (reference::ReferenceIntersection::Points(points), TriangleTriangleIntersection::Point(p)) => {
                assert!(points.iter().all(|q| p.distance(*q) <= tolerance), "case {index}: {result:?}, {expected:?}");
            },
            (reference::ReferenceIntersection::Points(points), TriangleTriangleIntersection::Segment(p, q)) => {
                assert!([p, q].iter().all(|endpoint| points.iter().any(|hit| hit.distance(*endpoint) <= tolerance)), "case {index}: {result:?}, {expected:?}");
            },
            _ => panic!("case {index}: {result:?}, {expected:?}"),
        }
    }
